// 输出类似：1年7月14天3小时25分钟30秒前
// 等 DOM 加载完成后更新容器
document.addEventListener('DOMContentLoaded', () => {
    const display = document.getElementById('time-display');
    if (display) {
        display.textContent = `📅 ${formatDetailedTime(date)}`;
    }
});